-- Schema-Fingerabdruck: gleiche Abfrage lokal (psql) und in Supabase (SQL Editor) ausführen
-- und die Hashes vergleichen. Abweichungen zeigen, in welchem Bereich sich die Datenbanken unterscheiden.
-- MAINTAIN (nur PostgreSQL 17) wird ausgeklammert, damit PG16 lokal und PG17 gehostet vergleichbar bleiben.
with
cols as (select string_agg(format('%s.%s:%s:%s:%s', c.table_name, c.column_name, c.udt_name, c.is_nullable, coalesce(c.column_default,'')), '|' order by c.table_name, c.ordinal_position) s, count(*) n from information_schema.columns c where c.table_schema = 'public'),
cons as (select string_agg(format('%s.%s:%s', cl.relname, co.conname, pg_get_constraintdef(co.oid)), '|' order by cl.relname, co.conname) s, count(*) n from pg_constraint co join pg_class cl on cl.oid = co.conrelid join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public'),
idx as (select string_agg(pg_get_indexdef(i.indexrelid), '|' order by pg_get_indexdef(i.indexrelid)) s, count(*) n from pg_index i join pg_class c on c.oid = i.indrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public'),
fns as (select string_agg(p.proname || ':' || md5(pg_get_functiondef(p.oid)), '|' order by p.proname, pg_get_function_identity_arguments(p.oid)) s, count(*) n from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f'),
pol as (select string_agg(format('%s.%s.%s:%s:%s:%s:%s', schemaname, tablename, policyname, cmd, roles::text, coalesce(qual,''), coalesce(with_check,'')), '|' order by schemaname, tablename, policyname) s, count(*) n from pg_policies where schemaname = 'public' or (schemaname = 'storage' and policyname like 'immovia%')),
trg as (select string_agg(pg_get_triggerdef(t.oid), '|' order by c.relname, t.tgname) s, count(*) n from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where not t.tgisinternal and (n.nspname = 'public' or (n.nspname = 'auth' and t.tgname like 'on_auth_user%'))),
tgr as (select string_agg(format('%s:%s:%s', c.relname, r.rolname, a.privilege_type), '|' order by c.relname, r.rolname, a.privilege_type) s, count(*) n from pg_class c join pg_namespace n on n.oid = c.relnamespace cross join lateral aclexplode(c.relacl) a join pg_roles r on r.oid = a.grantee where n.nspname = 'public' and c.relkind = 'r' and r.rolname in ('anon','authenticated','service_role') and a.privilege_type <> 'MAINTAIN'),
cgr as (select string_agg(format('%s.%s:%s:%s', c.relname, at.attname, r.rolname, a.privilege_type), '|' order by c.relname, at.attname, r.rolname, a.privilege_type) s, count(*) n from pg_attribute at join pg_class c on c.oid = at.attrelid join pg_namespace n on n.oid = c.relnamespace cross join lateral aclexplode(at.attacl) a join pg_roles r on r.oid = a.grantee where n.nspname = 'public' and c.relkind = 'r' and at.attnum > 0 and not at.attisdropped and r.rolname in ('anon','authenticated','service_role')),
fgr as (select string_agg(format('%s(%s):%s', p.proname, pg_get_function_identity_arguments(p.oid), r.rolname), '|' order by p.proname, pg_get_function_identity_arguments(p.oid), r.rolname) s, count(*) n from pg_proc p join pg_namespace n on n.oid = p.pronamespace cross join pg_roles r where n.nspname = 'public' and p.prokind = 'f' and r.rolname in ('anon','authenticated','service_role') and has_function_privilege(r.oid, p.oid, 'execute')),
rls as (select string_agg(c.relname || ':' || c.relrowsecurity, '|' order by c.relname) s, count(*) n from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'),
dat as (select md5(coalesce((select string_agg(to_jsonb(t)::text, '|' order by id) from (select id, name, description, is_premium, is_active, sort_order, config from public.dossier_templates) t),'') || coalesce((select string_agg(key || value::text || coalesce(description,''), '|' order by key) from public.feature_settings),'') || coalesce((select string_agg(to_jsonb(t)::text, '|' order by id) from (select id, name, audience, price_chf_monthly, limits, is_active from public.plans) t),'') || coalesce((select string_agg(format('%s:%s:%s:%s', id, public, file_size_limit, allowed_mime_types), '|' order by id) from storage.buckets where id in ('property-originals','property-images','documents','dossiers','avatars','org-logos','message-attachments')),'')) s),
pub as (select string_agg(tablename::text, ',' order by tablename) s from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public')
select 'cols' k, md5(s) h, n from cols union all select 'cons', md5(s), n from cons union all select 'idx', md5(s), n from idx union all select 'fns', md5(s), n from fns union all select 'pol', md5(s), n from pol union all select 'trg', md5(s), n from trg union all select 'tgr', md5(s), n from tgr union all select 'cgr', md5(s), n from cgr union all select 'fgr', md5(s), n from fgr union all select 'rls', md5(s), n from rls union all select 'dat', s, 0 from dat union all select 'pub', coalesce(s,''), 0 from pub;
